package io.aequicor.magicpaper.domain.tools

import io.aequicor.magicpaper.domain.CodingInteractionMode
import kotlin.test.Test
import kotlin.test.assertEquals

// A recorded pin of ToolDefinition.allowed and ToolDefinition.allowsAuthorityMode over every
// context the ten conjuncts read. The expected blocks are literals: a later change to the
// predicate must be pasted in deliberately, never regenerated from the predicate itself.
//
// The matrix covers the 37 definitions of ToolCatalog and SessionToolCatalog only. It does NOT
// cover the nine browser tools of
// magic-agent/runtime/impl/src/jvmMain/kotlin/io/aequicor/magicpaper/data/browser/BrowserToolCatalog.kt:
// they are built outside both catalogues and attached to the registry at runtime
// (AgentToolBridge.kt:47), so today they are allowed unconditionally. This block is not total
// coverage of what an agent may call.
//
// Conjunct 8 (native && mutating) and conjunct 9 (research_check) cannot fire through either
// production caller: ToolRegistry.available filters !native and ApplicationToolCommands.project
// registers only !native. Their rows are pinned here and nowhere else.
//
// Conjunct 5 is unreachable-false in production today, because ORCHESTRATOR and PLANNER contexts
// are only ever constructed with mode = PLANNING. This matrix is the only thing that would notice
// a later slice simplifying it away.

private val modes = listOf(CodingInteractionMode.CODE, CodingInteractionMode.RESEARCH, CodingInteractionMode.PLANNING)
private val roles = listOf(ToolRole.ORCHESTRATOR, ToolRole.PLANNER, ToolRole.WORKER, ToolRole.CHAT)
private val flags = listOf(false, true)
private val optionalIds = listOf(null, "set")

private fun context(mode: CodingInteractionMode, role: ToolRole, auxiliaryExecution: Boolean,
    planId: String?, stageId: String? = null, taskWorktreeId: String? = null) = ToolExecutionContext(
    projectId = "project", ownerSessionId = "owner", sessionId = "session", requestId = "request",
    role = role, mode = mode, planId = planId, stageId = stageId,
    auxiliaryExecution = auxiliaryExecution, taskWorktreeId = taskWorktreeId)

private fun render(bits: (ToolDefinition) -> String) =
    ToolCatalog.definitions.sortedBy { it.id }.joinToString("\n") { "${it.id} ${bits(it)}" }

class ToolAccessGoldenMatrixTest {
    // Both literals are positional, so an added or reordered enum value silently narrows what they
    // cover instead of failing. Compared in declaration order, which is the order they decode in.
    @Test fun theEnumeratedContextsCoverEveryModeAndRole() {
        assertEquals(CodingInteractionMode.entries.toList(), modes,
            "A CodingInteractionMode was added or reordered: ALLOWED_MATRIX and AUTHORITY_MATRIX no longer cover every " +
            "mode. Extend `modes` and re-record both literals from the new predicate.")
        assertEquals(ToolRole.entries.toList(), roles,
            "A ToolRole was added or reordered: ALLOWED_MATRIX and AUTHORITY_MATRIX no longer cover every role. " +
            "Extend `roles` and re-record both literals from the new predicate.")
    }

    // One line per tool: id, space, 192 characters of allowed(). Character index, most significant
    // factor first, is decoded as
    //   ((((mode * 4 + role) * 2 + auxiliaryExecution) * 2 + planId) * 2 + stageId) * 2 + taskWorktreeId
    // with mode in (CODE, RESEARCH, PLANNING), role in (ORCHESTRATOR, PLANNER, WORKER, CHAT),
    // auxiliaryExecution in (false, true) and each id in (null, set). Lines are sorted by tool id.
    @Test fun allowedMatrixMatchesTheRecordedPin() {
        val actual = render { definition ->
            buildString {
                for (mode in modes) for (role in roles) for (auxiliaryExecution in flags)
                    for (planId in optionalIds) for (stageId in optionalIds) for (taskWorktreeId in optionalIds)
                        append(if (definition.allowed(context(mode, role, auxiliaryExecution, planId, stageId, taskWorktreeId))) '1' else '0')
            }
        }
        assertEquals(ALLOWED_MATRIX, actual)
    }

    // One line per tool: id, space, 144 characters of allowsAuthorityMode(). Character index,
    // most significant factor first, is decoded as
    //   (((mode * 3 + ownerMode) * 4 + role) * 2 + auxiliaryExecution) * 2 + planId
    // with mode and ownerMode in (CODE, RESEARCH, PLANNING), role in (ORCHESTRATOR, PLANNER,
    // WORKER, CHAT), auxiliaryExecution in (false, true) and planId in (null, set).
    // Lines are sorted by tool id.
    @Test fun authorityModeMatrixMatchesTheRecordedPin() {
        val actual = render { definition ->
            buildString {
                for (mode in modes) for (ownerMode in modes) for (role in roles)
                    for (auxiliaryExecution in flags) for (planId in optionalIds)
                        append(if (definition.allowsAuthorityMode(context(mode, role, auxiliaryExecution, planId), ownerMode)) '1' else '0')
            }
        }
        assertEquals(AUTHORITY_MATRIX, actual)
    }
}

